import React from "react";
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer } from "recharts";

const CrimeStats = ({ crimes }) => {
  // Show loading if crimes data is undefined or empty
  if (!crimes || crimes.length === 0) {
    return <div>Loading crime statistics...</div>;
  }

  // Safely calculate total crimes
  const totalCrimes = crimes.reduce((acc, crime) => acc + (crime.count || 0), 0);

  return (
    <div>
      <h2>Crime Statistics</h2>
      <p>Total Crimes: {totalCrimes}</p>

      <ResponsiveContainer width="100%" height={300}>
        <BarChart data={crimes}>
          <XAxis dataKey="type" />
          <YAxis />
          <Tooltip />
          <Bar dataKey="count" fill="#8884d8" />
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
};

export default CrimeStats;
